'use strict';

function packCompiledRecords(records, options) {
  if (!Array.isArray(records)) throw new TypeError('records must be an array');
  for (const record of records) {
    if (!record || typeof record !== 'object' ||
        typeof record.location !== 'string' ||
        typeof record.source !== 'string' ||
        typeof record.format !== 'string') {
      throw new TypeError('each record must have string location, source, and format');
    }
  }
  if (!options || typeof options !== 'object' ||
      typeof options.makeKey !== 'function' ||
      typeof options.debug !== 'boolean' ||
      typeof options.base !== 'string') {
    throw new TypeError('invalid options');
  }
  const accept = options.accept === undefined ? () => true : options.accept;
  if (typeof accept !== 'function') throw new TypeError('accept must be a function');

  const output = [];
  for (const record of records) {
    if (record.format !== 'compiled') continue;
    const accepted = accept(record);
    if (typeof accepted !== 'boolean') throw new TypeError('accept must return a boolean');
    if (accepted) continue;

    const key = options.makeKey(record.location);
    if (!Number.isSafeInteger(key) || key < 0) throw new TypeError('invalid key');
    const prefix = options.base + '/';
    const relative = record.location.startsWith(prefix)
      ? record.location.slice(prefix.length)
      : record.location;
    const header = JSON.stringify({ key, debug: options.debug, relative }) + '\n';
    output.push([
      { ...record },
      Buffer.from(header, 'utf8'),
      Buffer.from(record.source, 'utf8')
    ]);
  }
  return output;
}

module.exports = { packCompiledRecords };

