'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['packCompiledRecords']);
const { packCompiledRecords } = api;

const records = [
  { location: '/base/one.js', source: 'alpha', format: 'compiled', extra: 1 },
  { location: '/base/raw.js', source: 'raw', format: 'source' },
  { location: '/baseball/two.js', source: 'β', format: 'compiled' }
];
const before = JSON.parse(JSON.stringify(records));
const keyCalls = [];
const acceptCalls = [];
const packed = packCompiledRecords(records, {
  base: '/base',
  debug: true,
  accept(record) {
    acceptCalls.push(record.location);
    return true;
  },
  makeKey(location) {
    keyCalls.push(location);
    return keyCalls.length - 1;
  }
});

assert.deepStrictEqual(acceptCalls, ['/base/one.js', '/baseball/two.js']);
assert.deepStrictEqual(keyCalls, ['/base/one.js', '/baseball/two.js']);
assert.strictEqual(packed.length, 2);
assert.deepStrictEqual(packed[0][0], records[0]);
assert.notStrictEqual(packed[0][0], records[0]);
assert.deepStrictEqual(packed[1][0], records[2]);
assert.notStrictEqual(packed[1][0], records[2]);
assert(Buffer.isBuffer(packed[0][1]));
assert(Buffer.isBuffer(packed[0][2]));
assert.notStrictEqual(packed[0][1], packed[1][1]);
assert.notStrictEqual(packed[0][2], packed[1][2]);
assert.strictEqual(packed[0][1].toString('utf8'), JSON.stringify({ key: 0, debug: true, relative: 'one.js' }) + '\n');
assert.strictEqual(packed[1][1].toString('utf8'), JSON.stringify({ key: 1, debug: true, relative: '/baseball/two.js' }) + '\n');
assert.strictEqual(packed[0][2].toString('utf8'), 'alpha');
assert.strictEqual(packed[1][2].toString('utf8'), 'β');
assert.deepStrictEqual(records, before);
packed[0][0].source = 'changed';
packed[0][2][0] = 0;
assert.strictEqual(records[0].source, 'alpha');

let rejectedKeyCalls = 0;
assert.deepStrictEqual(packCompiledRecords(records, {
  base: '/base', debug: false,
  accept: () => false,
  makeKey: () => { rejectedKeyCalls += 1; return 0; }
}), []);
assert.strictEqual(rejectedKeyCalls, 0);

assert.deepStrictEqual(packCompiledRecords([], {
  base: '', debug: false, makeKey: () => 0
}), []);

for (const bad of [null, {}, 'records']) {
  assert.throws(() => packCompiledRecords(bad, { base: '', debug: false, makeKey: () => 0 }), TypeError);
}
for (const badRecord of [null, {}, { location: 1, source: '', format: 'compiled' }, { location: '', source: 2, format: 'compiled' }, { location: '', source: '', format: 3 }]) {
  assert.throws(() => packCompiledRecords([badRecord], { base: '', debug: false, makeKey: () => 0 }), TypeError);
}

let prematureCalls = 0;
assert.throws(() => packCompiledRecords([
  { location: 'ok', source: 'x', format: 'compiled' },
  { location: 'bad', source: 1, format: 'compiled' }
], {
  base: '', debug: false,
  accept: () => { prematureCalls += 1; return true; },
  makeKey: () => { prematureCalls += 1; return 0; }
}), TypeError);
assert.strictEqual(prematureCalls, 0);

const valid = [{ location: 'x', source: 'y', format: 'compiled' }];
for (const options of [null, {}, { base: '', debug: false, makeKey: 1 }, { base: 1, debug: false, makeKey: () => 0 }, { base: '', debug: 0, makeKey: () => 0 }, { base: '', debug: false, makeKey: () => 0, accept: 1 }]) {
  assert.throws(() => packCompiledRecords(valid, options), TypeError);
}
assert.throws(() => packCompiledRecords(valid, { base: '', debug: false, accept: () => 'yes', makeKey: () => 0 }), TypeError);
for (const badKey of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, '0']) {
  assert.throws(() => packCompiledRecords(valid, { base: '', debug: false, makeKey: () => badKey }), TypeError);
}

